import{_ as o,l as p,o as a,c as s,v as c,p as i,x as r,d as u,i as l,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"cgroup CPU 组调度","description":"","frontmatter":{"title":"cgroup CPU 组调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cgroup-cpu-sched.md","filePath":"cs/cgroup-cpu-sched.md","lastUpdated":1789023840000}'),n={name:"cs/cgroup-cpu-sched.md"};function h(m,e,_,E,g,f){const t=p("Mermaid");return a(),s("div",null,[e[1]||(e[1]=c('<h1 id="cgroup-cpu-组调度" tabindex="-1">cgroup CPU 组调度 <a class="header-anchor" href="#cgroup-cpu-组调度" aria-label="Permalink to &quot;cgroup CPU 组调度&quot;">​</a></h1><div class="epigraph"><p>cpu 控制器把一组任务当成可加权的实体：组有 vruntime/份额，组内再分，使容器不能靠多线程骗走整机 CPU。</p><footer>—— 据 Linux cgroup v2 cpu 文档；内核 CFS 组调度说明</footer></div><p><a href="/cs/latency-measurement">上一课</a>留下的缺口接到本课。 <a href="/cs/memcg">memcg</a>/<a href="/cs/blkio-cgroup">blkio</a> 已限内存与 I/O。<a href="/cs/eevdf">EEVDF</a> 的任务是叶。缺口是 <strong>组调度</strong>：<code>cpu.weight</code>/<code>cpu.max</code> 如何进 runqueue。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十个线程 nice 0 会比一个线程多吃 CPU。组：容器整体权重 100，内部再抢。缺口：带宽 <code>cpu.max</code> 配额（quota/period）把组变成 DL 式的上限；实时任务是否进 cpu 控制器（配置而定）。本课不把 v1 cpu.shares 与 v2 weight 的换算表当正文。</p><p><span class="marginnote">层次化：父组限额约束子组。空闲组不积欠无限（实现有 clamp）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入队：任务挂到组实体，组实体挂到 CPU 的根。选择：先选组再选任务。对照 <a href="/cs/blk-schedulers">BFQ</a> 的 cgroup 权重。对照 <a href="/cs/socket-buffers">net</a>：网络另有控制器。对照 DEADLINE：cpu.max 是 CFS 组的限额，不是 SCHED_DEADLINE 本身。</p>',8)),(a(),i(d,null,{default:r(()=>[l(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20G%5B%22%E7%BB%84%E8%B0%83%E5%BA%A6%E5%AE%9E%E4%BD%93%22%5D%0A%20%20G%20--%3E%20RQ%5B%22CPU%20runqueue%22%5D%0A%20%20W%5B%22cpu.weight%22%5D%20--%3E%20G%0A%20%20M%5B%22cpu.max%22%5D%20--%3E%20THR%5B%22%E9%85%8D%E9%A2%9D%E7%94%A8%E5%B0%BD%E5%88%99%E8%8A%82%E6%B5%81%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=c('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>组调度把「容器是一个用户」收成调度实体，使多租户 CPU 公平不依赖线程数。它不提供硬实时除非配合 DL/RT 配置。不要写成云规格账单。与 <a href="/cs/eas-scheduling">EAS</a>：组 util 影响选核。</p><p>配额用尽时组内全部 CFS 任务睡到下周期，看起来像卡顿。</p><p>实现上：层次化份额是相对的，父组限额会切子组。cpu.max 用完后组内 CFS 全部睡到下个 period。实时任务是否受 cpu 控制器管取决于配置。 读法上只引用<a href="/cs/latency-measurement">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>cgroup CPU 组调度</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cpu.idle 的全部。不保证与 cpuset 的每个交叉。下一课可编程调度器：sched_ext。</p><p>版本字段会变，课序钉的是机制对象「cgroup CPU 组调度」，不是某一主线内核的结构体名。 后课默认：CFS/EEVDF 可按 cgroup 加权与限额。用 BPF 写调度器，下一课 sched_ext。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cpu 控制器让组成为调度实体。</li><li>weight 摊份额，max 封顶。</li><li>sched_ext 是下一课。</li><li>出处：cgroup v2 cpu；Linux 组调度。</li></ul>',11))])}const x=o(n,[["render",h]]);export{C as __pageData,x as default};
